    if (order === null || typeof order !== 'object' || Array.isArray(order)) {
      invalidOrderRejections.push({ id: null, reason: 'invalid_order' });
      continue;
    }

    const hasValidId = typeof order.id === 'string' && order.id.length > 0;
    if (!hasValidId) {
      invalidOrderRejections.push({ id: null, reason: 'invalid_order' });
      continue;
    }

