    if (!isValidPriority) {
      invalidOrderRejections.push({ id: order.id, reason: 'invalid_order' });
      continue;
    }

    if (order.priority === 'expedited') {
      validExpeditedOrders.push(order);
    } else {
      validNormalOrders.push(order);
    }
